"use client";

import type { Row, Cell, Header } from "@tanstack/react-table";
import { cn } from "cn";
import { ArrowDown, ArrowUp, ChevronsUpDown } from "lucide-react";
import { useContext } from "react";
import type { ComponentProps, ReactNode } from "react";

import { Checkbox } from "./checkbox";
import type { DataGridFeatures } from "./data-grid-columns";
import {
  DataGridContext,
  DataGridViewportContext,
  useDataGridContext,
} from "./data-grid-context";
import type { DataGridSurface } from "./data-grid-context";
import { DataGridEmpty, DataGridError } from "./data-grid-feedback";
import { dataGridLabels } from "./data-grid-labels";
import type { DataGridLabels } from "./data-grid-labels";
import type { DataGridContract, DataGridRowData } from "./data-grid-schema";

export type DataGridProps<C extends DataGridContract> =
  ComponentProps<"div"> & {
    grid: DataGridSurface<C>;
    variant?: "default" | "striped" | "bordered" | "plain";
    density?: "comfortable" | "compact";
    labels?: Partial<DataGridLabels>;
  };
export function DataGrid<C extends DataGridContract>({
  grid,
  variant = "default",
  density = "comfortable",
  labels,
  className,
  ...props
}: DataGridProps<C>) {
  return (
    <DataGridContext.Provider
      value={{
        density,
        grid,
        labels: { ...dataGridLabels, ...labels },
        variant,
      }}
    >
      <div
        {...props}
        data-slot="data-grid"
        data-variant={variant}
        data-density={density}
        className={cn("flex w-full min-w-0 flex-col gap-3", className)}
      />
    </DataGridContext.Provider>
  );
}
export function DataGridViewport({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <DataGridViewportContext.Provider value={true}>
      <div
        {...props}
        data-slot="data-grid-viewport"
        data-grid-scroll=""
        className={cn("relative min-w-0 overflow-auto rounded-md", className)}
      />
    </DataGridViewportContext.Provider>
  );
}

const cellBase = "text-start align-middle text-sm wrap-anywhere";
export function DataGridColumn({ className, ...props }: ComponentProps<"th">) {
  const { variant, density } = useDataGridContext();
  return (
    <th
      scope="col"
      {...props}
      data-slot="data-grid-column"
      className={cn(
        cellBase,
        "font-medium text-muted-foreground",
        density === "compact" ? "px-3 py-2" : "px-4 py-3",
        variant !== "plain" && "border-b",
        variant === "bordered" && "border-e last:border-e-0",
        className
      )}
    />
  );
}
export function DataGridCell({ className, ...props }: ComponentProps<"td">) {
  const { variant, density } = useDataGridContext();
  return (
    <td
      {...props}
      data-slot="data-grid-cell"
      className={cn(
        cellBase,
        density === "compact" ? "px-3 py-2" : "px-4 py-3",
        variant === "bordered" && "border-e last:border-e-0",
        className
      )}
    />
  );
}
export function DataGridRow({ className, ...props }: ComponentProps<"tr">) {
  const { variant } = useDataGridContext();
  return (
    <tr
      {...props}
      data-slot="data-grid-row"
      className={cn(
        "transition-colors motion-reduce:transition-none hover:bg-muted/50 data-[selected=true]:bg-accent",
        variant !== "plain" && "border-b last:border-b-0",
        variant === "striped" && "even:bg-muted/30",
        className
      )}
    />
  );
}

interface RenderContext<C extends DataGridContract, Native, Props> {
  grid: DataGridSurface<C>;
  row: DataGridRowData<C>;
  native: Native;
  props: Props;
}
export type DataGridTableProps<C extends DataGridContract> =
  ComponentProps<"table"> & {
    grid?: DataGridSurface<C>;
    stickyHeader?: boolean;
    renderRow?: (
      context: RenderContext<
        C,
        Row<DataGridFeatures, DataGridRowData<C>>,
        ComponentProps<"tr">
      >
    ) => ReactNode;
    renderCell?: (
      context: RenderContext<
        C,
        Cell<DataGridFeatures, DataGridRowData<C>, unknown>,
        ComponentProps<"td">
      > & { value: unknown }
    ) => ReactNode;
    renderColumn?: (context: {
      grid: DataGridSurface<C>;
      native: Header<DataGridFeatures, DataGridRowData<C>, unknown>;
      props: ComponentProps<"th">;
    }) => ReactNode;
    renderEmpty?: (context: {
      grid: DataGridSurface<C>;
      filtered: boolean;
      reset: () => void;
    }) => ReactNode;
    renderError?: (context: {
      grid: DataGridSurface<C>;
      error: unknown;
      retry: () => unknown;
      background: boolean;
    }) => ReactNode;
  };

export function DataGridTable<C extends DataGridContract>({
  grid: supplied,
  stickyHeader = false,
  renderRow,
  renderCell,
  renderColumn,
  renderEmpty,
  renderError,
  className,
  ...props
}: DataGridTableProps<C>) {
  const context = useDataGridContext<C>();
  const grid = supplied ?? context.grid;
  const { labels, variant } = context;
  const inViewport = useContext(DataGridViewportContext);
  const selection = grid.selectionMode !== "none";
  const span = Math.max(
    1,
    grid.table.getVisibleLeafColumns().length + Number(selection)
  );
  const { status } = grid.presentation;
  const selectionCell = (header: boolean, id?: string) => (
    <Checkbox
      aria-label={header ? labels.selectPage : labels.selectRow(id ?? "")}
      disabled={!grid.canSelectRows}
      checked={
        header ? grid.pageSelection.checked : grid.isRowSelected(id ?? "")
      }
      indeterminate={header && grid.pageSelection.indeterminate}
      onCheckedChange={(checked) =>
        header ? grid.togglePage(checked) : grid.toggleRow(id ?? "", checked)
      }
    />
  );
  const error = (background: boolean) =>
    renderError ? (
      renderError({
        background,
        error: grid.query.error,
        grid,
        retry: grid.query.refetch,
      })
    ) : (
      <DataGridError
        labels={labels}
        retry={grid.query.refetch}
        inline={background}
      />
    );
  const neutral = status === "paused" ? labels.paused : labels.inactive;
  const content = (
    <table
      {...props}
      data-slot="data-grid-table"
      aria-busy={
        status === "loading" ||
        status === "refreshing" ||
        status === "placeholder"
      }
      className={cn("w-full caption-bottom border-collapse text-sm", className)}
    >
      <thead
        className={cn(
          variant !== "plain" && "bg-muted/40",
          stickyHeader && "sticky top-0 z-10 bg-background"
        )}
      >
        {grid.table.getHeaderGroups().map((group) => (
          <tr key={group.id}>
            {selection && (
              <DataGridColumn className="w-10">
                {selectionCell(true)}
              </DataGridColumn>
            )}
            {group.headers.map((header) => {
              const sorted = header.column.getIsSorted();
              const label =
                grid.columns.find((column) => column.id === header.column.id)
                  ?.meta.dataGrid.label ?? header.column.id;
              const headerContent = <grid.table.FlexRender header={header} />;
              const columnProps: ComponentProps<"th"> = {
                "aria-sort": header.column.getCanSort()
                  ? sorted === "asc"
                    ? "ascending"
                    : sorted === "desc"
                      ? "descending"
                      : "none"
                  : undefined,
                children: header.column.getCanSort() ? (
                  <button
                    type="button"
                    className="inline-flex min-h-8 cursor-pointer items-center gap-2 rounded-sm text-start outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    aria-label={labels.sort(
                      label,
                      header.column.getNextSortingOrder()
                    )}
                    onClick={header.column.getToggleSortingHandler()}
                  >
                    {headerContent}
                    {sorted === "asc" ? (
                      <ArrowUp aria-hidden="true" className="size-3.5" />
                    ) : sorted === "desc" ? (
                      <ArrowDown aria-hidden="true" className="size-3.5" />
                    ) : (
                      <ChevronsUpDown aria-hidden="true" className="size-3.5" />
                    )}
                  </button>
                ) : (
                  headerContent
                ),
              };
              return (
                <FragmentColumn key={header.id}>
                  {renderColumn ? (
                    renderColumn({ grid, native: header, props: columnProps })
                  ) : (
                    <DataGridColumn {...columnProps} />
                  )}
                </FragmentColumn>
              );
            })}
          </tr>
        ))}
      </thead>
      <tbody>
        {grid.presentation.hasRows &&
          grid.table.getRowModel().rows.map((row) => {
            const rowProps: ComponentProps<"tr"> & { "data-selected": string } =
              {
                children: (
                  <>
                    {selection && (
                      <DataGridCell className="w-10">
                        {selectionCell(false, row.id)}
                      </DataGridCell>
                    )}
                    {row.getVisibleCells().map((cell) => {
                      const cellProps = {
                        children: <grid.table.FlexRender cell={cell} />,
                      };
                      return (
                        <FragmentColumn key={cell.id}>
                          {renderCell ? (
                            renderCell({
                              grid,
                              row: row.original,
                              native: cell,
                              value: cell.getValue(),
                              props: cellProps,
                            })
                          ) : (
                            <DataGridCell {...cellProps} />
                          )}
                        </FragmentColumn>
                      );
                    })}
                  </>
                ),
                "data-selected": String(grid.isRowSelected(row.id)),
              };
            return (
              <FragmentColumn key={row.id}>
                {renderRow ? (
                  renderRow({
                    grid,
                    native: row,
                    props: rowProps,
                    row: row.original,
                  })
                ) : (
                  <DataGridRow {...rowProps} />
                )}
              </FragmentColumn>
            );
          })}
        {status === "loading" &&
          !grid.presentation.hasRows &&
          Array.from({ length: 5 }, (_, index) => (
            <DataGridRow key={index} aria-hidden="true">
              {Array.from({ length: span }, (__, cell) => (
                <DataGridCell key={cell}>
                  <span className="block h-4 w-4/5 rounded bg-muted motion-safe:animate-pulse" />
                </DataGridCell>
              ))}
            </DataGridRow>
          ))}
        {!grid.presentation.hasRows && status !== "loading" && (
          <tr>
            <td colSpan={span}>
              {status === "error" ? (
                error(false)
              ) : status === "empty" ? (
                renderEmpty ? (
                  renderEmpty({
                    filtered: grid.filtered,
                    grid,
                    reset: grid.resetFilters,
                  })
                ) : (
                  <DataGridEmpty grid={grid} labels={labels} />
                )
              ) : (
                <div
                  className="px-4 py-10 text-center text-sm text-muted-foreground"
                  role="status"
                >
                  {neutral}
                </div>
              )}
            </td>
          </tr>
        )}
        {status === "backgroundError" && (
          <tr>
            <td colSpan={span}>{error(true)}</td>
          </tr>
        )}
      </tbody>
    </table>
  );
  return (
    <>
      {(status === "placeholder" ||
        status === "refreshing" ||
        status === "loading" ||
        (status === "paused" && grid.presentation.hasRows)) && (
        <div
          role="status"
          aria-live="polite"
          className="text-sm text-muted-foreground"
        >
          {status === "placeholder"
            ? labels.updating
            : status === "paused"
              ? labels.paused
              : status === "loading"
                ? labels.loading
                : labels.refreshing}
        </div>
      )}
      {inViewport ? (
        content
      ) : (
        <div
          data-grid-scroll=""
          className="relative min-w-0 overflow-auto rounded-md"
        >
          {content}
        </div>
      )}
    </>
  );
}
function FragmentColumn({ children }: { children: ReactNode }) {
  return <>{children}</>;
}

export {
  DataGridApplyFilters,
  DataGridColumnVisibility,
  DataGridFilter,
  DataGridPagination,
  DataGridResetFilters,
  DataGridSearch,
  DataGridSelectionBar,
  DataGridToolbar,
} from "./data-grid-controls";
export type { DataGridLabels } from "./data-grid-labels";

import {
  columnOrderingFeature,
  columnVisibilityFeature,
  createColumnHelper,
  rowPaginationFeature,
  rowSortingFeature,
  tableFeatures,
} from "@tanstack/react-table";
import type {
  CellContext,
  ColumnDef,
  HeaderContext,
} from "@tanstack/react-table";
import type { ReactNode } from "react";

import type {
  DataGridContract,
  DataGridRowData,
  DataGridSortKey,
} from "./data-grid-schema";

export const dataGridFeatures = tableFeatures({
  columnOrderingFeature,
  columnVisibilityFeature,
  rowPaginationFeature,
  rowSortingFeature,
});
export type DataGridFeatures = typeof dataGridFeatures;
export interface DataGridColumnMeta<S extends string = string> {
  label: string;
  sortBy?: S;
}
export type DataGridColumnDefinition<C extends DataGridContract> = ColumnDef<
  DataGridFeatures,
  DataGridRowData<C>,
  unknown
> & {
  id: string;
  meta: { dataGrid: DataGridColumnMeta<DataGridSortKey<C>> };
};
export interface DataGridCellContext<C extends DataGridContract, V> {
  value: V;
  row: DataGridRowData<C>;
  native: CellContext<DataGridFeatures, DataGridRowData<C>, V>;
}
interface ColumnOptions<C extends DataGridContract, V> {
  id?: string;
  header:
    | ReactNode
    | ((
        context: HeaderContext<DataGridFeatures, DataGridRowData<C>, unknown>
      ) => ReactNode);
  label?: string;
  sortBy?: DataGridSortKey<C>;
  enableHiding?: boolean;
  cell?: (context: DataGridCellContext<C, V>) => ReactNode;
}

export function createDataGridColumnHelper<C extends DataGridContract>(
  _contract: C
) {
  type R = DataGridRowData<C>;
  const native = createColumnHelper<DataGridFeatures, R>();

  function metadata<V>(options: ColumnOptions<C, V>) {
    const label =
      options.label ??
      (typeof options.header === "string" ? options.header : undefined);
    if (!label) {
      throw new Error("Non-text column headers require a text label");
    }
    return { dataGrid: { label, sortBy: options.sortBy } };
  }

  function accessor<K extends keyof R & string>(
    key: K,
    options: ColumnOptions<C, R[K]>
  ): DataGridColumnDefinition<C>;
  function accessor<V>(
    compute: (row: R) => V,
    options: ColumnOptions<C, V> & { id: string }
  ): DataGridColumnDefinition<C>;
  function accessor<V>(
    key: string | ((row: R) => V),
    options: ColumnOptions<C, V>
  ): DataGridColumnDefinition<C> {
    const id = options.id ?? (typeof key === "string" ? key : undefined);
    if (!id) {
      throw new Error("Computed columns require a stable ID");
    }
    const compute = typeof key === "function" ? key : (row: R) => row[key] as V;
    const definition = native.accessor(compute, {
      cell: (context) =>
        options.cell
          ? options.cell({
              value: context.getValue(),
              row: context.row.original,
              native: context,
            })
          : plainValue(context.getValue()),
      enableHiding: options.enableHiding,
      enableSorting: options.sortBy !== undefined,
      header: (context) =>
        typeof options.header === "function"
          ? options.header(
              context as HeaderContext<DataGridFeatures, R, unknown>
            )
          : options.header,
      id,
      meta: metadata(options),
      sortDescFirst: false,
    });
    // The value-specific renderer is closed over here; heterogeneous definitions
    // expose an unknown native value without requiring consumer any/casts.
    return definition as DataGridColumnDefinition<C>;
  }

  function display(
    options: Omit<ColumnOptions<C, never>, "cell" | "id"> & {
      id: string;
      cell?: (context: {
        row: R;
        native: CellContext<DataGridFeatures, R, unknown>;
      }) => ReactNode;
    }
  ): DataGridColumnDefinition<C> {
    if (!options.id) {
      throw new Error("Display columns require a stable ID");
    }
    return native.display({
      cell: (context) =>
        options.cell?.({ row: context.row.original, native: context }) ?? null,
      enableHiding: options.enableHiding,
      enableSorting: options.sortBy !== undefined,
      header: (context) =>
        typeof options.header === "function"
          ? options.header(context)
          : options.header,
      id: options.id,
      meta: metadata(options),
      sortDescFirst: false,
    }) as DataGridColumnDefinition<C>;
  }
  return { accessor, display };
}

function plainValue(value: unknown): ReactNode {
  if (value === null || value === undefined) {
    return "—";
  }
  return typeof value === "string" || typeof value === "number" ? value : "—";
}

export function normalizeDataGridColumns<C extends DataGridContract>(
  columns: readonly DataGridColumnDefinition<C>[]
) {
  const ids = new Set<string>();
  for (const column of columns) {
    if (ids.has(column.id)) {
      throw new Error(`Duplicate column ID: ${column.id}`);
    }
    ids.add(column.id);
  }
  return columns;
}

export function normalizeDataGridColumnOrder(
  saved: readonly string[],
  columns: readonly { id: string }[]
) {
  const known = new Set(columns.map((column) => column.id));
  return [
    ...new Set([
      ...saved.filter((id) => known.has(id)),
      ...columns.map((column) => column.id),
    ]),
  ];
}

export function normalizeDataGridColumnVisibility(
  saved: Record<string, boolean>,
  columns: readonly { id: string; enableHiding?: boolean }[]
) {
  return Object.fromEntries(
    columns.flatMap((column) =>
      column.enableHiding === false
        ? [[column.id, true]]
        : column.id in saved
          ? [[column.id, saved[column.id]]]
          : []
    )
  );
}

"use client";

import { createContext, useContext } from "react";

import type { DataGridLabels } from "./data-grid-labels";
import type { DataGridContract, DataGridOutput } from "./data-grid-schema";
import type { DataGridController } from "./use-data-grid";

export type DataGridSurface<C extends DataGridContract> = Omit<
  DataGridController<C>,
  "query"
> & {
  query: {
    data: DataGridOutput<C> | undefined;
    error: unknown;
    refetch: () => unknown;
  };
};
export const DataGridContext = createContext<{
  grid: unknown;
  labels: DataGridLabels;
  variant: "default" | "striped" | "bordered" | "plain";
  density: "comfortable" | "compact";
} | null>(null);
export const DataGridViewportContext = createContext(false);

export function useDataGridContext<
  C extends DataGridContract = DataGridContract,
>() {
  const context = useContext(DataGridContext);
  if (!context) {
    throw new Error("DataGrid components must be inside DataGrid");
  }
  return { ...context, grid: context.grid as DataGridSurface<C> };
}

"use client";

import { cn } from "cn";
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";
import { useId } from "react";
import type { ComponentProps, ReactNode } from "react";

import { Button } from "./button";
import { useDataGridContext } from "./data-grid-context";
import type { DataGridSurface } from "./data-grid-context";
import type { DataGridContract, DataGridFilterInput } from "./data-grid-schema";
import { getDataGridPageLinks } from "./data-grid-state";
import {
  DropdownRoot,
  DropdownTrigger,
  DropdownContent,
  DropdownCheckboxItem,
} from "./dropdown";
import { InputSearch } from "./input-search";
import type { InputSearchProps } from "./input-search";
import { Select } from "./select";

export function DataGridToolbar({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      {...props}
      data-slot="data-grid-toolbar"
      className={cn("flex min-w-0 flex-wrap items-center gap-2", className)}
    />
  );
}

export function DataGridFilter<
  C extends DataGridContract,
  K extends keyof DataGridFilterInput<C> & string,
>({
  grid,
  field,
  children,
}: {
  grid: DataGridSurface<C>;
  field: K;
  children: (binding: {
    value: DataGridFilterInput<C>[K];
    onChange: (value: DataGridFilterInput<C>[K]) => void;
    reset: () => void;
    error: string | undefined;
  }) => ReactNode;
}) {
  return children(grid.getFilterBinding(field));
}

type StringField<C extends DataGridContract> = {
  [K in keyof DataGridFilterInput<C>]: NonNullable<
    DataGridFilterInput<C>[K]
  > extends string
    ? K
    : never;
}[keyof DataGridFilterInput<C>] &
  string;
export function DataGridSearch<
  C extends DataGridContract,
  K extends StringField<C>,
>({
  grid,
  field,
  debounce = 300,
  onChange,
  ...props
}: Omit<InputSearchProps, "value" | "defaultValue"> & {
  grid: DataGridSurface<C>;
  field: K;
  debounce?: number;
}) {
  const { labels } = useDataGridContext();
  const id = useId();
  const binding = grid.getFilterBinding(field);
  const errorId = `${id}-error`;
  return (
    <div className="min-w-0">
      <InputSearch
        {...props}
        value={String(binding.value ?? "")}
        searchLabel={labels.search}
        clearLabel={labels.clearSearch}
        aria-invalid={Boolean(binding.error)}
        aria-describedby={
          binding.error
            ? [props["aria-describedby"], errorId].filter(Boolean).join(" ")
            : props["aria-describedby"]
        }
        onChange={(event) => {
          onChange?.(event);
          if (event.defaultPrevented) {
            return;
          }
          const { value } = event.currentTarget;
          grid.setFilter(field, value as DataGridFilterInput<C>[K], {
            debounce: value === "" ? 0 : debounce,
          });
        }}
      />
      {binding.error && (
        <p id={errorId} role="alert" className="mt-1 text-xs text-destructive">
          {binding.error}
        </p>
      )}
    </div>
  );
}

export function DataGridApplyFilters({
  onClick,
  children,
  ...props
}: ComponentProps<typeof Button>) {
  const { grid, labels } = useDataGridContext();
  return (
    <Button
      type="button"
      {...props}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) {
          grid.applyFilters();
        }
      }}
    >
      {children ?? labels.apply}
    </Button>
  );
}
export function DataGridResetFilters({
  onClick,
  children,
  ...props
}: ComponentProps<typeof Button>) {
  const { grid, labels } = useDataGridContext();
  return (
    <Button
      type="button"
      variant="outline"
      {...props}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) {
          grid.resetFilters();
        }
      }}
    >
      {children ?? labels.reset}
    </Button>
  );
}

export function DataGridColumnVisibility() {
  const { grid, labels } = useDataGridContext();
  return (
    <DropdownRoot>
      <DropdownTrigger
        render={<Button type="button" variant="outline" size="sm" />}
      >
        {labels.columns}
      </DropdownTrigger>
      <DropdownContent align="end">
        {grid.table
          .getAllLeafColumns()
          .filter((column) => column.getCanHide())
          .map((column) => (
            <DropdownCheckboxItem
              key={column.id}
              checked={column.getIsVisible()}
              onCheckedChange={(checked) => column.toggleVisibility(checked)}
            >
              {grid.columns.find((definition) => definition.id === column.id)
                ?.meta.dataGrid.label ?? column.id}
            </DropdownCheckboxItem>
          ))}
      </DropdownContent>
    </DropdownRoot>
  );
}

const DataGridPageLinks = ({
  links,
  index,
}: {
  links: (number | "ellipsis")[];
  index: number;
}) => {
  const { grid, labels } = useDataGridContext();
  return links.map((link, position) => {
    if (link === "ellipsis") {
      return (
        <span
          key={`gap-${position}`}
          aria-hidden="true"
          className="flex size-8 items-center justify-center text-muted-foreground"
        >
          …
        </span>
      );
    }
    return (
      <Button
        key={link}
        type="button"
        size="icon-sm"
        variant={link === index ? "default" : "outline"}
        data-page={link}
        aria-label={labels.page(link)}
        aria-current={link === index ? "page" : undefined}
        disabled={!grid.presentation.currentData}
        onClick={() => grid.table.setPageIndex(link - 1)}
        className="min-w-8 w-auto px-2 tabular-nums"
      >
        {link}
      </Button>
    );
  });
};

const usePaginationPresentation = (showPageNumbers: boolean) => {
  const { grid } = useDataGridContext();
  const { pagination } = grid.request;
  const { data } = grid.query;
  const page = "pageIndex" in pagination;
  const count =
    data && "rowCount" in data && !grid.presentation.placeholder
      ? data.rowCount
      : undefined;
  const from =
    count === undefined || count === 0 || !page
      ? 0
      : pagination.pageIndex * pagination.pageSize + 1;
  const to =
    count === undefined
      ? 0
      : Math.min(from === 0 ? 0 : from + pagination.pageSize - 1, count);
  const index = page ? pagination.pageIndex + 1 : grid.cursorHistory.index + 1;
  const numbered = page && showPageNumbers;
  const links =
    numbered && count !== undefined
      ? getDataGridPageLinks(index, grid.pageCount ?? 1)
      : [];
  return { count, from, index, links, numbered, page, pagination, to };
};

export function DataGridPagination({
  pageSizes = [25, 50, 100],
  showPageNumbers = true,
  className,
  ...props
}: ComponentProps<"div"> & {
  pageSizes?: readonly number[];
  showPageNumbers?: boolean;
}) {
  const { grid, labels } = useDataGridContext();
  const { count, from, index, links, numbered, page, pagination, to } =
    usePaginationPresentation(showPageNumbers);
  return (
    <div
      {...props}
      data-slot="data-grid-pagination"
      className={cn(
        "flex min-w-0 flex-wrap items-center justify-between gap-3 text-sm",
        className
      )}
    >
      <div className="text-muted-foreground">
        {page && count !== undefined
          ? labels.range(from, to, count)
          : labels.page(index)}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Select
          aria-label={labels.pageSize}
          data={pageSizes.map((value) => ({ label: String(value), value }))}
          value={pagination.pageSize}
          onValueChange={(value) => {
            if (value !== null) {
              grid.setPageSize(value);
            }
          }}
          size="sm"
        />
        {page && !numbered && (
          <Button
            type="button"
            size="icon-sm"
            variant="outline"
            disabled={!grid.canPreviousPage}
            onClick={() => grid.table.setPageIndex(0)}
            aria-label={labels.first}
          >
            <ChevronsLeft aria-hidden="true" />
          </Button>
        )}
        <Button
          type="button"
          size="icon-sm"
          variant="outline"
          disabled={!grid.canPreviousPage}
          onClick={() => grid.previousPage()}
          aria-label={labels.previous}
        >
          <ChevronLeft aria-hidden="true" />
        </Button>
        {links.length > 0 ? (
          <DataGridPageLinks links={links} index={index} />
        ) : (
          <span className="tabular-nums">
            {labels.page(
              index,
              page && count !== undefined ? grid.pageCount : undefined
            )}
          </span>
        )}
        <Button
          type="button"
          size="icon-sm"
          variant="outline"
          disabled={!grid.canNextPage}
          onClick={() => grid.nextPage()}
          aria-label={labels.next}
        >
          <ChevronRight aria-hidden="true" />
        </Button>
        {page && !numbered && (
          <Button
            type="button"
            size="icon-sm"
            variant="outline"
            disabled={!grid.canNextPage}
            onClick={() => grid.table.setPageIndex((grid.pageCount ?? 1) - 1)}
            aria-label={labels.last}
          >
            <ChevronsRight aria-hidden="true" />
          </Button>
        )}
      </div>
    </div>
  );
}

export function DataGridSelectionBar({
  className,
  ...props
}: ComponentProps<"div">) {
  const { grid, labels } = useDataGridContext();
  const all = grid.selection.mode === "allMatching";
  const count =
    grid.selection.mode === "explicit" ? grid.selection.ids.length : 0;
  if (!all && count === 0) {
    return null;
  }
  const { data } = grid.query;
  const total = data && "rowCount" in data ? data.rowCount : undefined;
  return (
    <div
      {...props}
      data-slot="data-grid-selection-bar"
      className={cn(
        "flex min-w-0 flex-wrap items-center gap-3 text-sm",
        className
      )}
    >
      <span role="status" aria-live="polite">
        {all ? labels.allMatching : labels.selected(count)}
      </span>
      {!all &&
        grid.selectionMode === "allMatching" &&
        grid.pageSelection.checked && (
          <Button
            type="button"
            variant="link"
            size="sm"
            disabled={!grid.canSelectRows}
            onClick={() => grid.selectAllMatching()}
          >
            {labels.selectAllMatching(total)}
          </Button>
        )}
      <Button
        type="button"
        variant="ghost"
        size="sm"
        onClick={() => grid.clearSelection()}
      >
        {labels.clearSelection}
      </Button>
    </div>
  );
}

